// === Tab: sketch ===
// By Roni Kaufman
// https://ronikaufman.github.io

// Made for Genuary 2025
// Day 15: Design a rug.

let palette = ["#050505", "#fffbe6"];

const MAX_SEED = 112358; // arbitrary big number
const N = 2; // recursion level

let points = [];

function setup() {
  createCanvas(500, 500);
  // noLoop() removed for animation
  noStroke();
	palette.push(random(["#2b67af", "#ef562f"]));
}

function draw() {
  createCompo(0, 0, width, random(MAX_SEED), N);
	for (let p of points) {
		let col = p.col;
		let r = red(window.color(col)), g = green(window.color(col)), b = blue(window.color(col));
		let no = random(-1, 1)*30;
		fill(r + no, g + no, b + no);
		square(p.x, p.y, p.s);
	}
}

// Central and axial symmetry!
// 0 1 2 1 0
// 1 3 4 3 1
// 2 4 5 4 2
// 1 3 4 3 1
// 0 1 2 1 0

function createCompo(x, y, s, seed, n) {
  if (n == 0) {
    makeSquare(x, y, s, seed);
    return;
  }

  randomSeed(seed);
  let seed0 = random(MAX_SEED);
  let seed1 = random(MAX_SEED);
  let seed2 = random(MAX_SEED);
  let seed3 = random(MAX_SEED);
  let seed4 = random(MAX_SEED);
  let seed5 = random(MAX_SEED);

  let seeds = [
    [seed0, seed1, seed2, seed1, seed0],
    [seed1, seed3, seed4, seed3, seed1],
    [seed2, seed4, seed5, seed4, seed2],
    [seed1, seed3, seed4, seed3, seed1],
    [seed0, seed1, seed2, seed1, seed0]
  ];

  for (let i = 0; i < 5; i++) {
    for (let j = 0; j < 5; j++) {
      createCompo(x+i*s/5, y+j*s/5, s/5, seeds[i][j], n-1);
    }
  }
}

function makeSquare(x, y, s, seed) {
  randomSeed(seed);

	let color0 = random(palette);
  let color1 = random(palette);
  let color2 = random(palette);
  let color3 = random(palette);
  let color4 = random(palette);
  let color5 = random(palette);

  let colors = [
    [color0, color1, color2, color1, color0],
    [color1, color3, color4, color3, color1],
    [color2, color4, color5, color4, color2],
    [color1, color3, color4, color3, color1],
    [color0, color1, color2, color1, color0]
  ];

  for (let i = 0; i < 5; i++) {
    for (let j = 0; j < 5; j++) {
			points.push({
				x: x+i*s/5,
				y: y+j*s/5,
				s: s/5,
				col: colors[i][j]
			})
    }
  }
}
